mapper.select:
select t0.*
from job_posts t0
where 1 = 1

    and t0.status = 'ACTIVE'
    and (t0.expired_at is null or t0.expired_at > current_timestamp)


    and (
        lower(t0.title) like lower(concat('%', #{query.keyword}, '%'))
        or lower(t0.description) like lower(concat('%', #{query.keyword}, '%'))
        or lower(t0.requirements) like lower(concat('%', #{query.keyword}, '%'))
        or lower(t0.position) like lower(concat('%', #{query.keyword}, '%'))
    )


    and t0.company_id = #{query.companyId}


    and t0.id in (
        select js.job_id from job_skills js where js.skill_id = #{query.skillId}
    )


    and t0.id in

        #{postId}



    and (

        (
            ${item.alias}${item.field} ${item.op}#{item.value}
             #{item1} 
         )

    )

order by


        ${query.sortBy} ${query.sortDirection}


        t0.created_at desc, t0.id desc
